//! The machine-readable CLI schema.
//!
//! One source of truth for `rcsr schema` and the GUI's `/api/schema`. The
//! option table, operator list, complexity formula and exit codes live here, so
//! adding a flag reaches both surfaces without a second edit (and without a
//! test that can only detect the drift after it happens).

use crate::expr::Op;
use crate::settings::Group;

const VERSION: &str = env!("CARGO_PKG_VERSION");

/// Whether `name` is one of the documented root search options.
pub fn has_option(name: &str) -> bool {
    options().iter().any(|(n, _, _, _)| *n == name)
}

/// The documented root options in document order: [`OPTIONS`] with each
/// anchor row replaced by its group's rows of the search setting table.
pub fn options() -> Vec<(&'static str, &'static str, &'static str, &'static str)> {
    let mut out = Vec::with_capacity(OPTIONS.len() + crate::settings::TABLE.len());
    for row in OPTIONS {
        match crate::settings::anchored(row) {
            Some(group) => out.extend(crate::settings::schema_rows(group)),
            None => out.push(*row),
        }
    }
    out
}

/// The hand option table used by `rcsr schema`, the GUI and the tests.
